/* fpu: directed FPU edge cases per FPU type (CONTRACT.md section 10, id 9).
 *
 * Expected values come from the MC68881/MC68882 User's Manual (2nd ed.), the
 * MC68040 User's Manual (section 9, FPU) and the MC68060 User's Manual
 * (section 6, FPU), for the FPU the probe found. The arithmetic/conversion
 * tables are generated by tools/gen_fpu.py with exact integer/Fraction
 * arithmetic (disk/modules/fpu_gen.s); everything else is in fpu_asm.s.
 * See docs/cases/fpu.md for every case id.
 */
#include "mod.h"

AMT_MODULE(fpu, 9, AMT_PH_BARE, AMT_MF_NEEDS_FPU, 0, 0);

/* ---- generated tables (fpu_gen.s) ---- */
struct fvec {
    UWORD op, flags;          /* flags: FPU mask bits 0-3, ulp tolerance 8-15 */
    ULONG fpcr;
    ULONG src[3], dst[3];     /* raw (FMOVEM) loads of FP1 / FP0; src is also the memory operand */
    ULONG res[3];             /* expected FP0 (or memory written by an out-conversion) */
    ULONG fpsr, fpsr_mask;
    ULONG res2[3];            /* expected FP2 (FSINCOS cosine; else +0) */
    ULONG rmask[3];           /* bits of res that are checked */
    const char *why;
};
struct fout { ULONG res[3], fpsr, res2[3]; };
struct fgroup { const char *name; const struct fvec *v; ULONG n; ULONG mask; };

extern const struct fgroup fpu_groups[];
extern const ULONG fpu_n_groups;
extern const char *const fpu_opnames[];
extern const UWORD fpu_pred_truth[32];

/* ---- fpu_asm.s ---- */
void fpu_exec(const struct fvec *v, struct fout *o);
ULONG fpu_pred(ULONG idx, ULONG fpsr_in);
extern volatile ULONG fpu_pred_fpsr;
void fpu_ftrap_handler(void);
ULONG fpu_pcr_get(void);
void fpu_pcr_set(ULONG pcr);
void fpu_reset(void);
void fpu_frestore_null_test(ULONG *out);
void fpu_frames(ULONG *out);
void fpu_frestore_bad(void);
void fpu_fmovem_static(const ULONG *src, ULONG *dst);
ULONG fpu_fmovem_predec(const ULONG *src, ULONG *dst_end);
void fpu_dyn_run(void);
extern UBYTE fpu_dyn_buf[320];
void fpu_ctl_rw(ULONG *out);
void fpu_const_regs(ULONG *out);
extern ULONG fpu_const_buf[];
void fpu_after_trap(ULONG *out);
void fpu_trap_run(void);
void fpu_exc_run(void);
struct tent { ULONG start, next; const char *name; ULONG data; UWORD vec, mask; };
struct xent { ULONG start, fnop; const char *name; ULONG data; UWORD vec, enable, excbit, mask; };
