#define FM_881 1
#define FM_882 2
#define FM_040 4
#define FM_060 8
#define FM_6888X 3
#define EXC_MID_6888X 0x8000

static UWORD fm;                 /* this FPU's mask bit */

/* ------------------------------------------------------------ formatting */
static char *hx(char *p, ULONG v, int digits)
{
    int i;
    for (i = digits - 1; i >= 0; i--) {
        int d = (v >> (i * 4)) & 15;
        *p++ = d < 10 ? '0' + d : 'a' + d - 10;
    }
    *p = 0;
    return p;
}

/* "llllllll.hhhhhhhh.llllllll" */
static void json_x(const char *key, const ULONG *x)
{
    char b[32], *p = b;
    p = hx(p, x[0], 8);
    *p++ = '.';
    p = hx(p, x[1], 8);
    *p++ = '.';
    hx(p, x[2], 8);
    json_str(key, b);
}

/* ------------------------------------------------------------ comparison */
typedef unsigned long long u64;

/* Mantissa bits below the FPCR rounding precision of a vector (single 24,
 * double 53, extended 64 bits): a tolerance counts in ulps of that precision,
 * and the result must be rounded to it. */
static int prec_shift(ULONG fpcr)
{
    switch ((fpcr >> 6) & 3) {
    case 1: return 40;
    case 2: return 11;
    default: return 0;
    }
}

static int ulp_ok(const ULONG *e, const ULONG *g, ULONG tol, int shift)
{
    ULONG ee = (e[0] >> 16) & 0x7fff, ge = (g[0] >> 16) & 0x7fff;
    u64 me = ((u64)e[1] << 32) | e[2], mg = ((u64)g[1] << 32) | g[2];
    u64 hi, lo, a, b, top;
    if ((e[0] ^ g[0]) & 0x80000000UL)
        return 0;
    if (ee == 0x7fff || ge == 0x7fff)
        return 0;
    if (mg & (((u64)1 << shift) - 1))
        return 0;   /* not rounded to the FPCR precision */
    me >>= shift;
    mg >>= shift;
    top = (u64)1 << (63 - shift);
    if (ee == ge) {
        u64 d = me > mg ? me - mg : mg - me;
        return d <= tol;
    }
    if (ee == ge + 1) {
        hi = me;
        lo = mg;
    } else if (ge == ee + 1) {
        hi = mg;
        lo = me;
    } else
        return 0;
    /* distance in units of the lower binade's ulp: 2*hi - lo */
    a = hi - top;
    b = (top << 1) - lo;
    if (a > tol || b > tol)
        return 0;
    return 2 * a + b <= tol;
}

/* distance in ulps (of the FPCR precision, see prec_shift()) for a failure report (-2: not rounded
 * to the FPCR precision; -1: different sign, non-finite or
 * more than one binade apart; capped at $7fffffff) */
static long ulp_dist(const ULONG *e, const ULONG *g, int shift)
{
    ULONG ee = (e[0] >> 16) & 0x7fff, ge = (g[0] >> 16) & 0x7fff;
    u64 me = (((u64)e[1] << 32) | e[2]) >> shift, mg = (((u64)g[1] << 32) | g[2]) >> shift, d;
    const u64 top = (u64)1 << (63 - shift);
    if (((e[0] ^ g[0]) & 0x80000000UL) || ee == 0x7fff || ge == 0x7fff)
        return -1;
    if ((((u64)g[1] << 32) | g[2]) & (((u64)1 << shift) - 1))
        return -2;
    if (ee == ge)
        d = me > mg ? me - mg : mg - me;
    else if (ee == ge + 1 || ge == ee + 1) {
        u64 hi = ee > ge ? me : mg, lo = ee > ge ? mg : me;
        u64 a = hi - top, b = (top << 1) - lo;
        if (a > 0x7fffffffULL || b > 0x7fffffffULL)
            return 0x7fffffffL;
        d = 2 * a + b;
    } else
        return -1;
    return d > 0x7fffffffULL ? 0x7fffffffL : (long)d;
}

static int x_ok(const ULONG *e, const ULONG *g, const ULONG *m, ULONG tol, int shift)
{
    if (!((e[0] ^ g[0]) & m[0]) && !((e[1] ^ g[1]) & m[1]) && !((e[2] ^ g[2]) & m[2]))
        return 1;
    return tol && ulp_ok(e, g, tol, shift);
}

static const ULONG all_ones[3] = { 0xffffffffUL, 0xffffffffUL, 0xffffffffUL };

static int vec_ok(const struct fvec *v, const struct fout *o)
{
    ULONG tol = v->flags >> 8;
    if ((o->fpsr ^ v->fpsr) & v->fpsr_mask)
        return 0;
    if (!x_ok(v->res, o->res, v->rmask, tol, prec_shift(v->fpcr)))
        return 0;
    return x_ok(v->res2, o->res2, all_ones, tol, prec_shift(v->fpcr));
}

/* ------------------------------------------------------------ tables */
#define MAXREP 6
static const struct fgroup *hot_g;
static struct fout hot_o;
static ULONG hot_bad_i;

static ULONG hot_fn(ULONG iter)
{
    const struct fgroup *g = hot_g;
    ULONG i;
    (void)iter;
    for (i = 0; i < g->n; i++) {
        const struct fvec *v = &g->v[i];
        if (!(v->flags & fm))
            continue;
        fpu_exec(v, &hot_o);
        if (!vec_ok(v, &hot_o)) {
            hot_bad_i = i;
            return i + 1;
        }
    }
    return 0;
}

static void vec_fields(const struct fvec *v, const struct fout *o, int full)
{
    char b[12];
    json_str("op", fpu_opnames[v->op]);
    hx(b, v->fpcr, 8);
    json_str("fpcr", b);
    json_x("src", v->src);
    json_x("dst", v->dst);
    json_x("exp_res", v->res);
    json_x("got_res", o->res);
    hx(b, v->fpsr, 8);
    json_str("exp_fpsr", b);
    hx(b, o->fpsr, 8);
    json_str("got_fpsr", b);
    if (full) {
        hx(b, v->fpsr_mask, 8);
        json_str("fpsr_checked", b);
        json_x("res_checked", v->rmask);
        if (v->flags >> 8)
            json_int("tol_ulp", v->flags >> 8);
    }
    if (v->flags >> 8)
        json_int("ulp_dist", ulp_dist(v->res, o->res, prec_shift(v->fpcr)));
    if (v->res2[0] | v->res2[1] | v->res2[2] | o->res2[0] | o->res2[1] | o->res2[2]) {
        json_x("exp_res2", v->res2);
        json_x("got_res2", o->res2);
    }
}

static void run_group(const struct fgroup *g)
{
    static struct fout bad_o[MAXREP];
    static UWORD bad_i[MAXREP];
    struct fout o;
    ULONG i, n = 0, nbad = 0, first = 0, badh = 0;
    long r;

    if (!(g->mask & fm))
        return;
    for (i = 0; i < g->n; i++) {
        const struct fvec *v = &g->v[i];
        if (!(v->flags & fm))
            continue;
        n++;
        fpu_exec(v, &o);
        if (!vec_ok(v, &o)) {
            if (nbad < MAXREP) {
                bad_o[nbad] = o;
                bad_i[nbad] = (UWORD)i;
            }
            nbad++;
        }
    }
    hot_g = g;
    r = amt_hot_checked(hot_fn, amt_hot_reps(), &first, &badh);
    if (!nbad && r >= 0) {
        bad_i[0] = (UWORD)hot_bad_i;
        bad_o[0] = hot_o;
        nbad = 1;
    }
    if (!nbad && r < 0) {
        amt_case(g->name, AMT_ST_PASS, 0);
        return;
    }
    amt_case_open(g->name, AMT_ST_FAIL);
    if (nbad) {
        const struct fvec *v = &g->v[bad_i[0]];
        char b[12];
        json_obj("in");
        json_str("op", fpu_opnames[v->op]);
        hx(b, v->fpcr, 8);
        json_str("fpcr", b);
        json_x("src", v->src);
        json_x("dst", v->dst);
        json_obj_end();
        json_obj("expect");
        json_x("res", v->res);
        hx(b, v->fpsr, 8);
        json_str("fpsr", b);
        if (v->res2[0] | v->res2[1] | v->res2[2] | bad_o[0].res2[0] | bad_o[0].res2[1] | bad_o[0].res2[2])
            json_x("res2", v->res2);
        json_obj_end();
        json_obj("got");
        json_x("res", bad_o[0].res);
        hx(b, bad_o[0].fpsr, 8);
        json_str("fpsr", b);
        if (v->res2[0] | v->res2[1] | v->res2[2] | bad_o[0].res2[0] | bad_o[0].res2[1] | bad_o[0].res2[2])
            json_x("res2", bad_o[0].res2);
        json_obj_end();
        json_str("why", v->why);
        json_obj("ctx");
        json_int("bad", (long)nbad);
        json_int("vectors", (long)n);
        hx(b, v->fpsr_mask, 8);
        json_str("fpsr_checked", b);
        json_x("res_checked", v->rmask);
        if (v->flags >> 8) {
            json_int("tol_ulp", v->flags >> 8);
            json_int("ulp_dist", ulp_dist(v->res, bad_o[0].res, prec_shift(v->fpcr)));
            if (v->res2[0] | v->res2[1] | v->res2[2])
                json_int("ulp_dist_res2", ulp_dist(v->res2, bad_o[0].res2, prec_shift(v->fpcr)));
        }
        json_str("note", "res/src/dst are extended: sign+exponent(16).pad(16), mantissa hi, mantissa lo; out-conversions show the memory written, left-aligned");
        if (nbad > 1) {
            json_arr("more");
            for (i = 1; i < nbad && i < MAXREP; i++) {
                json_obj(NULL);
                json_str("why", g->v[bad_i[i]].why);
                vec_fields(&g->v[bad_i[i]], &bad_o[i], 0);
                json_obj_end();
            }
            json_arr_end();
        }
        if (r >= 0) {
            json_int("hot_iteration", r);
            json_hex("hot_first", first);
            json_hex("hot_bad", badh);
        }
        json_obj_end();
    } else {
        json_obj("expect");
        json_hex("hash", first);
        json_obj_end();
        json_obj("got");
        json_hex("hash", badh);
        json_int("iteration", r);
        json_obj_end();
        json_str("why", "the vector table gave different results on a later repetition (hot loop: interpreter vs JIT-compiled code)");
        json_obj("ctx");
        json_int("vectors", (long)n);
        json_obj_end();
    }
    amt_case_close();
}

/* ------------------------------------------------------------ predicates */
static const char *const fam_name[4] = { "pred_fbcc", "pred_fscc", "pred_fdbcc", "pred_ftrapcc" };
static const char *const pred_names[32] = {
    "f", "eq", "ogt", "oge", "olt", "ole", "ogl", "or", "un", "ueq", "ugt", "uge", "ult", "ule", "ne", "t",
    "sf", "seq", "gt", "ge", "lt", "le", "gl", "gle", "ngle", "ngl", "nle", "nlt", "nge", "ngt", "sne", "st"
};
static int hot_fam;

/* condition codes an operation can produce: N with at most one of Z, I, NAN
 * (i = N<<3 | Z<<2 | I<<1 | NAN). Other combinations can only be written
 * with FMOVE to FPSR; the predicates are not specified for them. */
static int cc_valid(ULONG i)
{
    ULONG c = i & 7;
    return c == 0 || c == 1 || c == 2 || c == 4;
}

static ULONG pred_sweep(ULONG iter)
{
    ULONG p, i, h = 0;
    (void)iter;
    for (p = 0; p < 32; p++)
        for (i = 0; i < 16; i++) {
            ULONG r;
            if (!cc_valid(i))
                continue;
            r = fpu_pred(hot_fam * 32 + p, i << 24);
            h = ((h << 3) | (h >> 29)) ^ r ^ fpu_pred_fpsr;
        }
    return h;
}

/* pred_ccr: FScc and FBcc must not change the integer CCR (PRM: condition
 * codes not affected). The stubs (families 4 FScc, 5 FBcc) set CCR $15,
 * then $0A, before the instruction and read it right after (FBcc on the
 * taken and on the untaken path): $150a when kept. A JIT that keeps the
 * 68k CCR in the host flags can lose it there, so the sweep also runs in
 * the hot loop and every iteration is checked. */
#define PRED_CCR_KEPT 0x150aUL
static int ccr_fams[2], ccr_nfams;
static ULONG ccr_bad, ccr_bfam, ccr_bp, ccr_bi, ccr_got;
static long ccr_iter;

static ULONG pred_ccr_sweep(ULONG iter)
{
    ULONG p, i, h = 0;
    int f;
    for (f = 0; f < ccr_nfams; f++)
        for (p = 0; p < 32; p++)
            for (i = 0; i < 16; i++) {
                ULONG r;
                if (!cc_valid(i))
                    continue;
                r = fpu_pred((ULONG)ccr_fams[f] * 32 + p, i << 24) & 0xffff;
                if (r != PRED_CCR_KEPT) {
                    if (!ccr_bad) {
                        ccr_bfam = (ULONG)ccr_fams[f]; ccr_bp = p; ccr_bi = i; ccr_got = r; ccr_iter = (long)iter;
                    }
                    ccr_bad++;
                }
                h = ((h << 3) | (h >> 29)) ^ r;
            }
    return h;
}

static void case_pred_ccr(int fscc)
{
    ULONG first = 0, badh = 0;
    long r;
    ccr_nfams = 0;
    if (fscc)
        ccr_fams[ccr_nfams++] = 4;
    ccr_fams[ccr_nfams++] = 5;
    ccr_bad = 0;
    ccr_iter = -1;
    pred_ccr_sweep(0xffffffffUL);            /* once directly (interpreted) */
    r = amt_hot(pred_ccr_sweep, amt_hot_reps() / 10, &first, &badh);
    if (!ccr_bad && r < 0) {
        amt_case("pred_ccr", AMT_ST_PASS, 0);
        return;
    }
    amt_case_open("pred_ccr", AMT_ST_FAIL);
    if (ccr_bad) {
        json_obj("in");
        json_str("insn", ccr_bfam == 4 ? "fscc d2" : "fbcc.w");
        json_str("predicate", pred_names[ccr_bp]);
        json_int("pred", (long)ccr_bp);
        json_hex("fpsr", ccr_bi << 24);
        json_str("ccr_before", "15 then 0a");
        json_obj_end();
        json_obj("expect");
        json_hex("ccr", PRED_CCR_KEPT);
        json_obj_end();
        json_obj("got");
        json_hex("ccr", ccr_got);
        json_obj_end();
        json_str("why", "FScc/FBcc changed the integer CCR (PRM FScc/FBcc: condition codes not affected); "
                        "ccr = CCR after the instruction with $15 before << 8 | with $0A before "
                        "(FBcc: read on the taken or the untaken path)");
        json_obj("ctx");
        json_int("bad", (long)ccr_bad);
        json_int("iteration", ccr_iter);     /* -1: the first, direct sweep */
        json_str("fams", ccr_nfams == 2 ? "FScc FBcc" : "FBcc");
        if (r >= 0)
            json_int("hot_iteration", r);
        json_obj_end();
    } else {
        json_obj("expect");
        json_hex("hash", first);
        json_obj_end();
        json_obj("got");
        json_hex("hash", badh);
        json_int("iteration", r);
        json_obj_end();
        json_str("why", "the CCR sweep changed on a later repetition (interpreter vs JIT)");
    }
    amt_case_close();
}

static void run_pred(int fam)
{
    ULONG p, i, nbad = 0, first = 0, badh = 0;
    ULONG bp = 0, bi = 0, bres = 0, bfpsr = 0, eres = 0, efpsr = 0;
    long r;
    for (p = 0; p < 32; p++)
        for (i = 0; i < 16; i++) {
            ULONG in = i << 24, res, ef, er;
            if (!cc_valid(i))
                continue;
            res = fpu_pred(fam * 32 + p, in);
            er = (fpu_pred_truth[p] >> i) & 1;
            ef = in;
            if ((p & 0x10) && (i & 1))
                ef |= 0x8080;            /* BSUN + accrued IOP */
            if (res != er || fpu_pred_fpsr != ef) {
                if (!nbad) {
                    bp = p; bi = i; bres = res; bfpsr = fpu_pred_fpsr; eres = er; efpsr = ef;
                }
                nbad++;
            }
        }
    hot_fam = fam;
    r = amt_hot(pred_sweep, amt_hot_reps() / 10, &first, &badh);
    if (!nbad && r < 0) {
        amt_case(fam_name[fam], AMT_ST_PASS, 0);
        return;
    }
    amt_case_open(fam_name[fam], AMT_ST_FAIL);
    if (nbad) {
        json_obj("in");
        json_str("predicate", pred_names[bp]);
        json_int("pred", (long)bp);
        json_hex("fpsr", bi << 24);
        json_obj_end();
        json_obj("expect");
        json_int("taken", (long)eres);
        json_hex("fpsr", efpsr);
        json_obj_end();
        json_obj("got");
        json_int("taken", (long)bres);
        json_hex("fpsr", bfpsr);
        json_obj_end();
        json_str("why", "conditional predicate wrong for this FPSR condition code (N Z I NAN), or BSUN/IOP not set exactly for the IEEE-nonaware predicates ($10-$1F) with NAN set (MC68881 UM 4.?, Table of conditional tests; PRM 3-?)");
        json_obj("ctx");
        json_int("bad", (long)nbad);
        json_int("combos", 256);
        json_str("taken_means", fam == 0 ? "FBcc branched" : fam == 1 ? "FScc set $FF (0 = $00; 2 = any other byte, or the upper bytes of D0 changed)" :
                 fam == 2 ? "FDBcc fell through with the counter unchanged (2 = counter wrong)" :
                 "FTRAPcc trapped (vector 7 count)");
        if (r >= 0)
            json_int("hot_iteration", r);
        json_obj_end();
    } else {
        json_obj("expect");
        json_hex("hash", first);
        json_obj_end();
        json_obj("got");
        json_hex("hash", badh);
        json_int("iteration", r);
        json_obj_end();
        json_str("why", "predicate sweep changed on a later repetition (interpreter vs JIT)");
    }
    amt_case_close();
}

/* ------------------------------------------------------------ traps */
static ULONG at[8];

/* addresses are reported as offsets from the instruction under test
 * (start), so the records do not depend on where the module was loaded */
static void trap_ctx(ULONG start, ULONG next, int code)
{
    int fmt = amt_last_exc.frame[3] >> 12;
    json_obj("got");
    json_int("code", code);
    if (!code) {
        json_str("trap", "none: the instruction completed");
        json_hex("fpsr", at[4]);
        json_int("fpiar_off", (long)(at[5] - start));
        json_obj_end();
    } else {
        json_int("vector", amt_last_exc.vector);
        json_int("pc_off", (long)(amt_last_exc.pc - start));
        json_hexn("sr", amt_last_exc.frame[0], 4);
        json_hexn("format_vector", amt_last_exc.frame[3], 4);
        if (fmt == 2 || fmt == 3)
            json_int("frame_addr_off", (long)((((ULONG)amt_last_exc.frame[4] << 16) |
                                               amt_last_exc.frame[5]) - start));
        if (fmt == 9) {
            json_int("frame_insn_off", (long)((((ULONG)amt_last_exc.frame[4] << 16) |
                                               amt_last_exc.frame[5]) - start));
            json_hexn("frame_opword", amt_last_exc.frame[7], 4);
        }
        json_int("fsave_bytes", (long)at[0]);
        json_hex("fsave0", at[1]);
        json_hex("fsave1", at[2]);
        json_hex("fpsr", at[4]);
        json_int("fpiar_off", (long)(at[5] - start));
        json_obj_end();
    }
    json_obj("ctx");
    if (next)
        json_int("next_off", (long)(next - start));
    json_str("offsets", "pc_off/fpiar_off/frame_addr_off/next_off: bytes from the instruction under test");
    json_obj_end();
}

static int fmt_allowed(int fmt, const UBYTE *list)
{
    while (*list != 0xff) {
        if (*list == fmt)
            return 1;
        list++;
    }
    return 0;
}

static const UBYTE f_0[] = { 0, 0xff };
static const UBYTE f_2[] = { 2, 0xff };
static const UBYTE f_9[] = { 9, 0xff };
static const UBYTE f_02[] = { 0, 2, 0xff };
static const UBYTE f_03[] = { 0, 3, 0xff };
static const UBYTE f_023[] = { 0, 2, 3, 0xff };

static int hardware_fpu_policy(const char *id)
{
    if (!(amt_par.flags & AMT_F_FPUCOMPAT))
        return 0;
    amt_case(id, AMT_ST_UNTESTABLE,
             "configured FPU compatibility policy (fpu_no_unimplemented=false) emulates this hardware-unimplemented instruction/data type or disabled exception; hardware trap expectation requires the strict FPU-policy lane");
    return 1;
}

static void run_traps(void)
{
    ULONG i;
    for (i = 0; i < fpu_n_trap; i++) {
        const struct tent *e = &fpu_trap_tab[i];
        int code, ok, fmt;
        const UBYTE *fl;
        const char *why = 0;
        if (!(e->mask & fm))
            continue;
        if (hardware_fpu_policy(e->name))
            continue;
        fpu_trap_idx = i;
        code = amt_try(fpu_trap_run);
        fpu_after_trap(at);
        fmt = amt_last_exc.frame[3] >> 12;
        if (e->vec == 11 && (fm & FM_6888X))
            fl = f_0;                    /* 020/030 F-line: format 0 */
        else if (e->vec == 11)
            fl = (fm & FM_040) ? f_2 : f_02;
        else if (e->vec == 60)
            fl = f_02;
        else
            fl = f_023;
        ok = code == AMT_ABORT_UNEXPECTED && amt_last_exc.vector == e->vec;
        if (!ok)
            why = e->vec == 11 ? (fm & FM_6888X ?
                    "6888x: the 040/060-only opmode must be an illegal coprocessor command -> F-line exception (vector 11), MC68881 UM 7.?, MC68020 UM 10.?" :
                    "unimplemented on this FPU: with no FPSP (bare metal) the instruction must take the F-line/unimplemented-FP-instruction exception, vector 11 (MC68040 UM 9.?, MC68060 UM 6.?); Amiberry: fpu_no_unimplemented=false emulates it instead") :
                  e->vec == 60 ? "68060: dynamic FMOVEM.X / FMOVEM.L #imm of several control registers / #imm .X are unimplemented effective addresses: vector 60 (MC68060 UM 6.?)" :
                  "unsupported data type (packed decimal, denormal or unnormal operand) must take vector 55 on the 040/060 with no FPSP (MC68040 UM 9.?, MC68060 UM 6.?)";
        else if ((amt_last_exc.frame[3] & 0xfff) != e->vec * 4 || !fmt_allowed(fmt, fl))
            why = "wrong exception stack frame format/vector offset";
        else if (amt_last_exc.pc != e->start && amt_last_exc.pc != e->next)
            why = "stacked PC is neither the instruction nor the next one";
        else if (e->vec == 11 && (fm & FM_040) && (((at[1] >> 24) & 0xfe) != 0x40 || ((at[1] >> 16) & 0xff) != 0x30))
            why = "68040 after an unimplemented FP instruction: FSAVE must give the unimp frame (version $40/$41, size $30) the FPSP needs (MC68040 UM 9.?)";
        else if (e->vec == 55 && (fm & FM_040) && (((at[1] >> 24) & 0xfe) != 0x40 ||
                 (((at[1] >> 16) & 0xff) != 0x30 && ((at[1] >> 16) & 0xff) != 0x60)))
            why = "68040 after an unsupported data type exception: FSAVE must give a non-idle frame (unimp $30 or busy $60)";
        else if (e->vec == 55 && (fm & FM_060) && ((at[1] >> 8) & 0xff) != 0xe0 && ((at[1] >> 8) & 0xff) != 0x60)
            why = "68060 after an unsupported data type exception: FSAVE frame format byte must be $E0 (EXCP) or $60 (IDLE)";
        amt_case_open(e->name, why ? AMT_ST_FAIL : AMT_ST_PASS);
        if (why) {
            json_obj("expect");
            json_int("vector", e->vec);
            json_str("format", fl == f_0 ? "0" : fl == f_2 ? "2" : fl == f_02 ? "0|2" : "0|2|3");
            json_str("pc", "insn|next");
            json_obj_end();
            trap_ctx(e->start, e->next, code);
            json_str("why", why);
        }
        amt_case_close();
    }
}

static void run_excs(void)
{
    ULONG i;
    for (i = 0; i < fpu_n_exc; i++) {
        const struct xent *e = &fpu_exc_tab[i];
        int code, fmt;
        const char *why = 0;
        const UBYTE *fl;
        ULONG hot_rep = 0;
        if (!(e->mask & fm))
            continue;
        if (!e->enable && hardware_fpu_policy(e->name))
            continue;
        fpu_exc_idx = i;
        code = amt_try(fpu_exc_run);
        fpu_after_trap(at);
        fmt = amt_last_exc.frame[3] >> 12;
        fl = (fm & FM_6888X) ? ((e->mask & EXC_MID_6888X) ? f_9 : f_0) :
             (e->vec == 48 ? f_023 : f_03);
        if (code != AMT_ABORT_UNEXPECTED || amt_last_exc.vector != e->vec)
            why = "enabled FPU exception (FPCR enable byte) must trap through its vector: 48 BSUN, 49 INEX, 50 DZ, 51 UNFL, 52 OPERR, 53 OVFL, 54 SNAN (MC68881 UM 6.1, MC68040 UM 9.?, MC68060 UM 6.?)";
        else if ((amt_last_exc.frame[3] & 0xfff) != e->vec * 4 || !fmt_allowed(fmt, fl))
            why = "wrong exception stack frame format/vector offset";
        else if (amt_last_exc.pc != e->start && amt_last_exc.pc != e->fnop)
            why = "stacked PC is neither the operation nor the following FNOP";
        else if (fl == f_9 && (amt_last_exc.pc != e->fnop ||
                 (((ULONG)amt_last_exc.frame[4] << 16) | amt_last_exc.frame[5]) != e->start))
            why = "6888x move-out mid-instruction frame must contain the next instruction as ScanPC and the operation address at +$08 (MC68881/MC68882 UM 7.4.2.6, figure 7-16)";
        else if (!(at[4] & e->excbit))
            why = "the FPSR exception status bit of the trapped exception is not set";
        else if (e->vec != 48 && at[5] != e->start)
            why = "FPIAR must hold the address of the instruction that caused the exception";
        /* Then again and again, until a JIT has compiled the trapping code
         * (its exception paths: a compiled instruction that hands enabled or
         * pending exceptions to the interpreter): the same trap every time. */
        if (!why) {
            ULONG r, reps = amt_hot_reps() * 2;
            for (r = 1; r <= reps && !why; r++) {
                code = amt_try(fpu_exc_run);
                fpu_after_trap(at);
                if (code != AMT_ABORT_UNEXPECTED || amt_last_exc.vector != e->vec ||
                    !(at[4] & e->excbit))
                    why = "repeated (hot, compiled by a JIT): the enabled FPU exception must still trap through its vector with its FPSR status bit set";
            }
            if (why)
                hot_rep = r - 1;
        }
        amt_case_open(e->name, why ? AMT_ST_FAIL : AMT_ST_PASS);
        if (why) {
            json_obj("expect");
            json_int("vector", e->vec);
            json_str("format", fl == f_0 ? "0" : fl == f_9 ? "9" : fl == f_03 ? "0|3" : "0|2|3");
            json_hexn("fpsr_bit", e->excbit, 4);
            json_int("fpiar_off", 0);
            json_obj_end();
            trap_ctx(e->start, e->fnop, code);
            json_str("why", why);
            if (hot_rep)
                json_int("hot_repetition", hot_rep);
            json_obj("in");
            json_hexn("fpcr", e->enable, 4);
            json_obj_end();
        }
        amt_case_close();
    }
}

/* ------------------------------------------------------------ single cases */
static const ULONG xnan[3] = { 0x7fff0000UL, 0xffffffffUL, 0xffffffffUL };

static void case_frestore_null(void)
{
    static ULONG out[27];
    int i, bad = -1;
    fpu_frestore_null_test(out);
    for (i = 0; i < 3; i++)
        if (out[i])
            bad = i;
    for (i = 0; i < 8 && bad < 0; i++)
        if (out[3 + i * 3] != xnan[0] || out[4 + i * 3] != xnan[1] || out[5 + i * 3] != xnan[2])
            bad = 3 + i;
    if (bad < 0) {
        amt_case("frestore_null_nan", AMT_ST_PASS, 0);
        return;
    }
    amt_case_open("frestore_null_nan", AMT_ST_FAIL);
    json_obj("expect");
    json_hex("fpcr", 0);
    json_hex("fpsr", 0);
    json_hex("fpiar", 0);
    json_x("fp0_7", xnan);
    json_obj_end();
    json_obj("got");
    json_hex("fpcr", out[0]);
    json_hex("fpsr", out[1]);
    json_hex("fpiar", out[2]);
    json_arr("fp");
    for (i = 0; i < 8; i++) {
        char b[32], *p = b;
        p = hx(p, out[3 + i * 3], 8); *p++ = '.';
        p = hx(p, out[4 + i * 3], 8); *p++ = '.';
        hx(p, out[5 + i * 3], 8);
        json_str(NULL, b);
    }
    json_arr_end();
    json_obj_end();
    json_obj("in");
    json_str("before", "FPCR=$30 FPSR=$0F00FFF8 FPIAR=$12345678 FP0-7=1..8, then FRESTORE of a null frame");
    json_obj_end();
    json_str("why", "FRESTORE of a null frame resets the FPU: FPCR/FPSR/FPIAR = 0 and FP0-FP7 = NaN $7FFF FFFFFFFF FFFFFFFF (MC68881 UM 6.4.?/FRESTORE, MC68040 UM 9.?, MC68060 UM 6.?)");
    amt_case_close();
}

static void case_frames(void)
{
    static ULONG o[16];
    const char *why = 0;
    ULONG nsz, isz, nb, iv, isize;
    fpu_frames(o);
    nsz = o[0];
    isz = o[4];
    nb = o[1];
    iv = o[5] >> 24;
    isize = (o[5] >> 16) & 0xff;
    /* null frame */
    if (fm & FM_060) {
        if (nsz != 12 || ((nb >> 8) & 0xff) != 0)
            why = "68060 null FSAVE frame: 12 bytes with frame format byte (byte 2) $00 (MC68060 UM 6.?)";
    } else if (nsz != 4 || (nb >> 24) != 0)
        why = "null FSAVE frame after a null FRESTORE: one longword with version byte $00 (MC68881 UM 6.4, MC68040 UM 9.?); the size byte is not checked";
    amt_case_open("fsave_null_frame", why ? AMT_ST_FAIL : AMT_ST_PASS);
    if (why) {
        json_obj("expect");
        json_int("bytes", (fm & FM_060) ? 12 : 4);
        json_str("frame", (fm & FM_060) ? "xxxx00xx" : "00xxxxxx");
        json_obj_end();
        json_obj("got");
        json_int("bytes", (long)nsz);
        json_hex("frame0", o[1]);
        json_hex("frame1", o[2]);
        json_hex("frame2", o[3]);
        json_obj_end();
        json_str("why", why);
    }
    amt_case_close();

    /* idle frame */
    why = 0;
    if (fm & FM_060) {
        if (isz != 12 || ((o[5] >> 8) & 0xff) != 0x60)
            why = "68060 idle FSAVE frame: 12 bytes, frame format byte $60 (MC68060 UM 6.?)";
    } else if (fm & FM_040) {
        if (isz != 4 || (iv != 0x41 && iv != 0x40) || isize != 0)
            why = "68040 idle FSAVE frame: one longword, version $41 (or $40), size $00 (MC68040 UM 9.?)";
    } else {
        ULONG want = (fm & FM_881) ? 0x18 : 0x38;
        if (iv == 0 || isize != want || isz != isize + 4)
            why = "6888x idle FSAVE frame: version byte nonzero, size $18 (68881) / $38 (68882), frame = size + 4 bytes (MC68881 UM 6.4.?)";
    }
    amt_case_open("fsave_idle_frame", why ? AMT_ST_FAIL : AMT_ST_PASS);
    if (why) {
        json_obj("expect");
        json_str("frame", (fm & FM_060) ? "xxxx60xx, 12 bytes" : (fm & FM_040) ? "41000000, 4 bytes" :
                 (fm & FM_881) ? "vv180000, 28 bytes" : "vv380000, 60 bytes");
        json_obj_end();
        json_obj("got");
        json_int("bytes", (long)isz);
        json_hex("frame0", o[5]);
        json_hex("frame1", o[6]);
        json_obj_end();
        json_str("why", why);
    }
    amt_case_close();

    /* round trip */
    why = 0;
    if (o[8] != o[9])
        why = "FSAVE after FRESTORE of an idle frame gave a different frame header";
    else if (o[10] != 0x20 || o[11] != 0x08000000UL || o[12] != 0x00c0ffeeUL)
        why = "FSAVE/FRESTORE of an idle frame changed FPCR/FPSR/FPIAR";
    else if (o[13] != 0x3ffd0000UL || o[14] != 0xaaaaaaaaUL || o[15] != 0xaaaaaaaaUL)
        why = "FSAVE/FRESTORE of an idle frame changed FP3 (or FDIV 1/3 in RM is wrong)";
    amt_case_open("fsave_frestore_roundtrip", why ? AMT_ST_FAIL : AMT_ST_PASS);
    if (why) {
        static const ULONG e3[3] = { 0x3ffd0000UL, 0xaaaaaaaaUL, 0xaaaaaaaaUL };
        json_obj("expect");
        json_hex("fpcr", 0x20);
        json_hex("fpsr", 0x08000000UL);
        json_hex("fpiar", 0x00c0ffeeUL);
        json_x("fp3", e3);
        json_hex("frame0", o[8]);
        json_obj_end();
        json_obj("got");
        json_hex("fpcr", o[10]);
        json_hex("fpsr", o[11]);
        json_hex("fpiar", o[12]);
        json_x("fp3", &o[13]);
        json_hex("frame0", o[9]);
        json_obj_end();
        json_str("why", why);
    }
    amt_case_close();
}

static void case_frestore_bad(void)
{
    int code = amt_try(fpu_frestore_bad);
    fpu_reset();
    if (code == AMT_ABORT_UNEXPECTED && amt_last_exc.vector == 14) {
        amt_case("frestore_bad_frame", AMT_ST_PASS, 0);
        return;
    }
    amt_case_open("frestore_bad_frame", AMT_ST_FAIL);
    json_obj("expect");
    json_int("vector", 14);
    json_obj_end();
    json_obj("got");
    json_int("code", code);
    json_int("vector", code ? amt_last_exc.vector : -1);
    if (code)
        json_int("pc_off_from_routine", (long)(amt_last_exc.pc - (ULONG)fpu_frestore_bad));
    json_obj_end();
    json_obj("in");
    json_str("frame", "5a5a5a5a 00000000 00000000 ...");
    json_obj_end();
    json_str("why", "FRESTORE of a frame with an invalid version/format must take a format error (vector 14) (MC68020 UM 10.?, MC68040 UM 9.?, MC68060 UM 6.?)");
    amt_case_close();
}

static void case_ctl(void)
{
    ULONG o[3];
    fpu_ctl_rw(o);
    /* FPCR bits 3-0 are unused; on the 68040 they are not documented as
     * reading zero, so both $FFF0 and $FFFF are accepted there */
    if ((fm & FM_040) && o[0] == 0x0000ffffUL)
        o[0] = 0x0000fff0UL;
    if (o[0] == 0x0000fff0UL && o[1] == 0x0ffffff8UL && o[2] == 0xffffffffUL) {
        amt_case("ctl_reg_bits", AMT_ST_PASS, 0);
        return;
    }
    amt_case_open("ctl_reg_bits", AMT_ST_FAIL);
    json_obj("expect");
    json_hex("fpcr", 0x0000fff0UL);
    json_hex("fpsr", 0x0ffffff8UL);
    json_hex("fpiar", 0xffffffffUL);
    json_obj_end();
    json_obj("got");
    json_hex("fpcr", o[0]);
    json_hex("fpsr", o[1]);
    json_hex("fpiar", o[2]);
    json_obj_end();
    json_obj("in");
    json_str("written", "ffffffff to each");
    json_obj_end();
    json_str("why", "unused FPCR bits (31-16, 3-0) and FPSR bits (31-28, 2-0) read as zero; FPIAR is 32 bits (MC68881 UM 1.?/2.?, MC68040 UM 9.?)");
    amt_case_close();
}

/* FP0-FP7 special values for FMOVEM: +0, -inf, QNaN, SNaN, denormal,
 * unnormal, max, -1.5 */
static const ULONG mv_src[24] = {
    0x00000000UL, 0, 0,
    0xffff0000UL, 0, 0,
    0x7fff0000UL, 0xc0000000UL, 0,
    0x7fff0000UL, 0xa0000000UL, 0x00000001UL,
    0x00000000UL, 0x00000000UL, 0x00000001UL,
    0x3fff0000UL, 0x40000000UL, 0,
    0x7ffe0000UL, 0xffffffffUL, 0xffffffffUL,
    0xbfff0000UL, 0xc0000000UL, 0
};

static void report_mem(const char *id, const ULONG *e, const ULONG *g, int nl, const char *why, ULONG extra_e, ULONG extra_g)
{
    int i;
    amt_case_open(id, AMT_ST_FAIL);
    json_obj("expect");
    json_arr("x");
    for (i = 0; i < nl; i += 3)
        json_x(NULL, &e[i]);
    json_arr_end();
    if (extra_e != extra_g)
        json_hex("an", extra_e);
    json_obj_end();
    json_obj("got");
    json_arr("x");
    for (i = 0; i < nl; i += 3)
        json_x(NULL, &g[i]);
    json_arr_end();
    if (extra_e != extra_g)
        json_hex("an", extra_g);
    json_obj_end();
    json_str("why", why);
    amt_case_close();
}

static int eq(const ULONG *a, const ULONG *b, int n)
{
    int i;
    for (i = 0; i < n; i++)
        if (a[i] != b[i])
            return 0;
    return 1;
}

static void case_fmovem(void)
{
    static ULONG d[24 + 4];
    ULONG endp, want;
    int code, i;
    static const UBYTE order[8] = { 0, 0, 2, 1, 2, 5, 3, 7 };   /* source index per FP0..FP7 */
    static ULONG e[24];

    for (i = 0; i < 28; i++)
        d[i] = 0x55555555UL;
    fpu_fmovem_static(mv_src, d);
    if (eq(mv_src, d, 24) && d[24] == 0x55555555UL)
        amt_case("fmovem_static", AMT_ST_PASS, 0);
    else
        report_mem("fmovem_static", mv_src, d, 24,
                   "FMOVEM.X moves registers without conversion: +0, -inf, QNaN, SNaN, denormal, unnormal, max, -1.5 must come back bit-exact (MC68881 UM 4.?/FMOVEM; MC68040 UM 9.?)", 0, 0);

    for (i = 0; i < 28; i++)
        d[i] = 0x55555555UL;
    want = (ULONG)&d[24] - 96;
    endp = fpu_fmovem_predec(mv_src, &d[24]);
    if (eq(mv_src, d, 24) && endp == want)
        amt_case("fmovem_predec", AMT_ST_PASS, 0);
    else
        report_mem("fmovem_predec", mv_src, d, 24,
                   "FMOVEM.X FP0-FP7,-(An): FP0 at the lowest address, An decremented by 96 (PRM FMOVEM: predecrement mask order); an = final An minus its start",
                   want - (ULONG)&d[24], endp - (ULONG)&d[24]);

    /* dynamic lists */
    for (i = 0; i < 96; i++)
        fpu_dyn_buf[i] = ((const UBYTE *)mv_src)[i];
    for (i = 96; i < 320; i++)
        fpu_dyn_buf[i] = 0x55;
    fpu_dyn_buf[192] = 0xa5;
    fpu_dyn_buf[193] = 0x5a;
    code = amt_try(fpu_dyn_run);
    if ((fm & FM_060) && !(amt_par.flags & AMT_F_FPUCOMPAT)) {
        fpu_after_trap(at);
        if (code == AMT_ABORT_UNEXPECTED && amt_last_exc.vector == 60)
            amt_case("fmovem_dynamic", AMT_ST_PASS, 0);
        else {
            amt_case_open("fmovem_dynamic", AMT_ST_FAIL);
            json_obj("expect");
            json_int("vector", 60);
            json_obj_end();
            trap_ctx((ULONG)fpu_dyn_run, 0, code);
            json_str("why", "68060: FMOVEM.X with a dynamic register list is an unimplemented effective address: vector 60 (MC68060 UM 6.?)");
            amt_case_close();
        }
        return;
    }
    {
        static ULONG st[12], all[24];
        const ULONG *gs = (const ULONG *)(fpu_dyn_buf + 96);
        const ULONG *ga = (const ULONG *)(fpu_dyn_buf + 208);
        for (i = 0; i < 3; i++) {
            st[i] = mv_src[0 * 3 + i];
            st[3 + i] = mv_src[2 * 3 + i];
            st[6 + i] = mv_src[5 * 3 + i];
            st[9 + i] = mv_src[7 * 3 + i];
        }
        for (i = 0; i < 8; i++) {
            all[i * 3] = mv_src[order[i] * 3];
            all[i * 3 + 1] = mv_src[order[i] * 3 + 1];
            all[i * 3 + 2] = mv_src[order[i] * 3 + 2];
        }
        for (i = 0; i < 24; i++)
            e[i] = all[i];
        if (code)
            report_mem("fmovem_dynamic", st, st, 0, "dynamic FMOVEM.X trapped on a 6888x/68040 or under the explicit 68060 FPU compatibility policy", 0, 1);
        else if (!eq(st, gs, 12) || gs[12] != 0x55555555UL)
            report_mem("fmovem_dynamic", st, gs, 12,
                       "FMOVEM.X D0,(An) with D0=$A5 (control mode, bit 7 = FP0) must store FP0, FP2, FP5, FP7 in that order and nothing more", 0, 0);
        else if (!eq(e, ga, 24))
            report_mem("fmovem_dynamic", e, ga, 24,
                       "FMOVEM.X (An)+,D1 with D1=$5A must load FP1, FP3, FP4, FP6 from consecutive memory (FP0-7 shown after)", 0, 0);
        else
            amt_case("fmovem_dynamic", AMT_ST_PASS, 0);
    }
}

/* --------------------------------------------- constant 68k registers */
/* fpu_const_regs(): Dn/An set from constants right before FPU instructions
 * that read or write them. A JIT that keeps such constants in its own state
 * must store them before an FPU instruction that uses the registers in
 * memory (a helper call, the interpreter handler), and must not store the
 * constant over a value the FPU instruction wrote. Hot, so it is compiled. */
static const char *const const_what[6] = {
    "FPCR after FMOVE.L D0,FPCR (D0 = $10 from MOVE.L #imm)",
    "D1 after FMOVE.L FP0,D1 (FP0 = 7; D1 = 5 from MOVEQ before)",
    "FPIAR after FMOVE.L D2,FPIAR (D2 = $12345678 from MOVE.L #imm)",
    "A1 after FMOVE.S (A1)+,FP1 (A1 from LEA): advanced by 4",
    "FP1 after FMOVE.S (A1)+,FP1 (2.0), as an integer",
    "D3 after FSEQ D3 (D3 = -1 from MOVEQ; the result 2.0 is not zero): low byte cleared",
};
static ULONG const_got[6], const_want[6], const_bad_i;

static ULONG const_fn(ULONG iter)
{
    ULONG i;
    (void)iter;
    fpu_const_regs(const_got);
    for (i = 0; i < 6; i++)
        if (const_got[i] != const_want[i]) {
            const_bad_i = i;
            return i + 1;
        }
    return 0;
}

static void case_const_regs(void)
{
    ULONG first, bad;
    long r;
    const_want[0] = 0x10;
    const_want[1] = 7;
    const_want[2] = 0x12345678UL;
    const_want[3] = (ULONG)fpu_const_buf + 4;
    const_want[4] = 2;
    const_want[5] = 0xffffff00UL;
    r = amt_hot_checked(const_fn, amt_hot_reps(), &first, &bad);
    fpu_reset();
    if (r < 0) {
        amt_case("const_regs", AMT_ST_PASS, 0);
        return;
    }
    amt_case_open("const_regs", AMT_ST_FAIL);
    json_obj("expect");
    json_hexn("value", const_want[const_bad_i], 8);
    json_obj_end();
    json_obj("got");
    json_hexn("value", const_got[const_bad_i], 8);
    json_obj_end();
    json_str("what", const_what[const_bad_i]);
    json_int("hot_repetition", r);
    json_str("why", "a register set from a constant just before an FPU instruction must be the value the FPU instruction reads, and the value it writes must stay");
    amt_case_close();
}

/* ------------------------------------------------------------ main */
void amt_run_fpu(void)
{
    ULONG i, pcr = 0;
    int is060 = AMT_FPU() == AMT_FPU_68060;

    switch (AMT_FPU()) {
    case AMT_FPU_68881: fm = FM_881; break;
    case AMT_FPU_68882: fm = FM_882; break;
    case AMT_FPU_68040: fm = FM_040; break;
    default: fm = FM_060; break;
    }
    if (is060) {
        pcr = fpu_pcr_get();
        if (pcr & 2)
            fpu_pcr_set(pcr & ~2UL);        /* PCR.DFP: enable the FPU */
    }
    amt_vec_set(7, fpu_ftrap_handler);

    case_frestore_null();
    case_frames();
    case_frestore_bad();
    case_ctl();
    fpu_reset();
    for (i = 0; i < fpu_n_groups; i++)
        run_group(&fpu_groups[i]);
    for (i = 0; i < 4; i++)
        if (i == 0 || !is060 || (amt_par.flags & AMT_F_FPUCOMPAT))
            run_pred((int)i);
    case_pred_ccr(!is060 || (amt_par.flags & AMT_F_FPUCOMPAT));
    case_fmovem();
    case_const_regs();
    run_traps();
    run_excs();

    fpu_reset();
    if (is060 && (pcr & 2))
        fpu_pcr_set(pcr);
}
